def pdf(name,title,lines):
 c=canvas.Canvas(str(M/name),pagesize=A4);c.setTitle(title);w,h=A4;c.setFillColorRGB(.97,.96,.91);c.rect(0,0,w,h,fill=1,stroke=0);c.setFillColorRGB(.16,.2,.15);c.setFont('Iansui',24);c.drawString(44,h-65,title);c.setFont('Iansui',13);y=h-108
 for line in lines:
  if not line:y-=18;continue
  for i in range(0,len(line),35):c.drawString(44,y,line[i:i+35]);y-=23
 c.setFont('Iansui',10);c.drawString(44,35,'Learn AI with Tarshar｜2026　課堂虛構資料');c.save()
