css='''@font-face{font-family:Iansui;src:url('Iansui-Regular.ttf')} :root{--bg:#efe5cf;--text-1:#302a20;--text-2:#4c483b;--text-3:#706b5b;--accent:#49644b;--surface:#fffdf2;--mint:#d5e4d0;--rose:#f1d3cf;--yellow:#f8edbc;--border:#82765f;--shadow:3px 5px 0 #c6bea655;--font-sans:Iansui,'Kaiti TC',serif;--font-display:var(--font-sans);--font-mono:var(--font-sans)}body{background:var(--bg);overflow:hidden}.deck{width:1280px;height:720px;position:absolute;left:50%;top:calc(50% - 27px);transform:translate(-50%,-50%) scale(var(--scale,1));transform-origin:center}.slide{padding:54px 88px 65px;background:url('paper.png') center/100% 100%;justify-content:flex-start;transition:none;transform:none}.slide:not(.is-active){visibility:hidden}.slide.is-active{visibility:visible}.slide.cover{padding:0}.fullcover{width:100%;height:100%;object-fit:cover}.kicker{font-size:19px;letter-spacing:1px;margin:0 0 8px;color:var(--accent)}.h2{font:700 43px/1.3 var(--font-sans);margin:0 0 30px;display:table;background:linear-gradient(transparent 65%,var(--yellow) 65%,var(--yellow) 95%,transparent 95%)}.grid.g2{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:stretch;flex:1;min-height:0}.paper{position:relative;padding:27px 28px 22px;background:var(--surface);border:1.8px solid var(--border);border-radius:3px 9px 30px 4px;box-shadow:var(--shadow)}.paper:before{content:'';position:absolute;top:-12px;left:25px;width:100px;height:25px;transform:rotate(-5deg);background:var(--mint);opacity:.85}.paper.rose:before{background:var(--rose)}.paper.yellow:before{background:var(--yellow)}.paper h3{font-size:30px;margin:0 0 20px}.paper p{font-size:27px;line-height:1.7;margin:14px 0}.paper b{font-size:25px;line-height:1.6}.paper.mint{background:linear-gradient(var(--mint),var(--mint)) 0 0/100% 12px no-repeat,var(--surface)}.paper.rose{background:linear-gradient(var(--rose),var(--rose)) 0 0/100% 12px no-repeat,var(--surface)}.paper.yellow{background:linear-gradient(var(--yellow),var(--yellow)) 0 0/100% 12px no-repeat,var(--surface)}.tipline{font-size:23px;line-height:1.4;margin:25px 0 0;align-self:center;background:var(--yellow);padding:7px 18px;border-radius:3px;max-width:100%}.steps{padding-left:31px;margin:10px 0}.steps li{font-size:26px;line-height:1.6;margin:14px 0}.promptbox{position:relative;background:var(--surface);border:2px solid var(--border);border-radius:4px 4px 28px 4px;box-shadow:var(--shadow);padding:24px 30px}.promptbox .label{position:absolute;top:-17px;background:var(--mint);padding:3px 16px;font-size:22px;transform:rotate(-1deg)}.prompttext{font-size:27px;line-height:1.7;margin:9px 0 12px}.copy,.download{border:1px solid var(--accent);color:var(--accent);border-radius:4px;background:var(--surface);padding:8px 13px;font:22px var(--font-sans);display:inline-block;margin:5px 5px 5px 0;cursor:pointer}.copy{background:var(--mint)}.big{font-size:39px;line-height:1.5}.handbig{font-size:31px!important}.art{width:380px;margin:10px auto;max-height:245px;object-fit:contain;mix-blend-mode:multiply}.slidefoot{position:absolute;bottom:31px;left:89px;right:89px;display:flex;justify-content:space-between;font-size:16px;color:var(--text-3)}.answer{border-collapse:collapse;width:100%;font-size:27px;background:var(--surface)}.answer th{background:var(--mint)}.answer td,.answer th{border:1px solid var(--border);padding:14px 20px;text-align:left;line-height:1.5}.calendar{border:2px solid var(--border);background:var(--surface);border-radius:8px;align-self:center}.calhead{background:var(--mint);font-size:26px;padding:15px}.event{display:flex;gap:16px;padding:18px;border-top:1px solid var(--border);font-size:25px}.event>b{min-width:75px}.event span{border-left:5px solid var(--accent);padding-left:12px}.event small{display:block;font-size:20px;margin-top:6px}.polaroid{background:var(--surface);padding:13px 13px 17px;box-shadow:var(--shadow);border:1px solid var(--border);align-self:center;transform:rotate(-1deg)}.polaroid img{width:100%}.polaroid p{text-align:center;font-size:20px}.route{display:flex;gap:13px;align-items:stretch;margin:55px 0}.route>div{background:var(--surface);padding:20px 12px;flex:1;border:1px solid var(--border);transform:rotate(-2deg);box-shadow:var(--shadow)}.route>div:nth-child(2n){transform:rotate(2deg);background:var(--mint)}.route b{font-size:38px}.route h3{font-size:24px;margin:10px 0}.route p{font-size:24px}.five{display:flex;gap:12px;margin-top:30px}.five span{padding:12px;background:var(--mint);font-size:23px;flex:1;text-align:center}.break{text-align:center;margin:auto}.break>span{font-size:95px}.break h2{font-size:45px}.break p{font-size:31px}.finish{background:var(--surface);padding:35px 50px;border:2px solid var(--border);box-shadow:var(--shadow);margin:10px auto;transform:rotate(-1deg)}.finish h2{font-size:36px}.finish p{font-size:28px;line-height:2.1}mark{background:var(--yellow);padding:3px 9px;color:var(--text-1)}.finish mark{font-size:30px}.controls{position:fixed;bottom:0;left:0;right:0;height:54px;display:flex;align-items:center;justify-content:center;gap:10px;background:var(--accent);z-index:20}.controls button,.controls a{font:16px var(--font-sans);border:0;padding:7px 14px;border-radius:4px;background:var(--surface);color:var(--text-1);cursor:pointer}.controls span{font-size:16px;color:var(--surface);min-width:60px;text-align:center}.progress-bar{bottom:54px}.slide-number{display:none}.notes{display:none}.reading{overflow:auto}.reading .deck{position:static;transform:none;width:min(100%,1000px);height:auto;margin:0 auto;padding-bottom:65px}.reading .slide{position:relative;visibility:visible!important;opacity:1;pointer-events:auto;inset:auto;transform:none!important;margin:0 0 25px;width:100%;height:auto;min-height:500px;background-size:100% 100%;padding:45px 55px 60px}.reading .slide.cover{padding:0;min-height:0}.reading .slidefoot{bottom:23px;left:45px;right:45px}.reading .art{height:220px}.reading .route{margin:20px 0}.reading .slide:not(.is-active){display:flex}.reading .h2{margin-bottom:28px}.reading .prompttext{font-size:24px}.reading .grid{min-height:auto}.reading .paper{min-height:260px}.reading .controls{height:auto;min-height:54px;flex-wrap:wrap}.reading .progress-bar{display:none}[data-preview='1'] .controls{display:none}@media(max-width:600px){.reading .slide{padding:36px 24px 65px;min-height:0}.reading .h2{font-size:29px}.reading .kicker{font-size:16px}.reading .grid.g2{grid-template-columns:1fr;gap:26px}.reading .paper{padding:20px;min-height:0}.reading .paper h3{font-size:25px}.reading .paper p,.reading .paper b,.reading .steps li,.reading .prompttext{font-size:21px}.reading .promptbox{padding:24px 18px 15px}.reading .promptbox .label{font-size:17px}.reading .tipline{font-size:19px}.reading .route{flex-wrap:wrap}.reading .route>div{flex:1 1 40%}.reading .answer{font-size:18px}.reading .answer td,.reading .answer th{padding:9px 6px}.reading .five{flex-wrap:wrap}.reading .five span{font-size:18px}.reading .slidefoot{font-size:10px;left:23px;right:23px}.reading .finish{padding:20px}.reading .finish h2{font-size:27px}.reading .finish p,.reading .finish mark{font-size:20px}.controls{gap:5px}.controls button,.controls a{font-size:13px;padding:7px 8px}.reading .polaroid{min-width:0}}@media print{@page{size:1280px 720px;margin:0}body{overflow:visible!important}.deck,.reading .deck{position:static;transform:none;width:1280px!important;height:auto;padding:0}.slide,.reading .slide{display:flex!important;position:relative!important;visibility:visible!important;opacity:1!important;transform:none!important;width:1280px!important;height:720px!important;min-height:720px!important;margin:0!important;break-after:page;padding:54px 88px 65px!important}.slide.cover{padding:0!important}.grid.g2{grid-template-columns:1fr 1fr!important}.controls,.progress-bar,.copy{display:none!important}.slidefoot{bottom:31px!important}.notes{display:none!important}}'''
