js='''function fit(){document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1280,(innerHeight-58)/720));}fit();addEventListener('resize',fit);const jump=d=>document.dispatchEvent(new KeyboardEvent('keydown',{key:d,bubbles:true}));document.querySelector('#prev').onclick=()=>jump('ArrowLeft');document.querySelector('#next').onclick=()=>jump('ArrowRight');document.querySelector('#read').onclick=()=>{document.body.classList.toggle('reading');document.querySelector('#read').textContent=document.body.classList.contains('reading')?'投影模式':'手機閱讀';};document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.parentElement.querySelector('.prompttext').textContent);b.textContent='已複製 ✓';}catch{b.textContent='請長按文字複製';}});new MutationObserver(()=>{document.querySelector('#counter').textContent=document.querySelectorAll('.slide').length?'第 '+([...document.querySelectorAll('.slide')].findIndex(s=>s.classList.contains('is-active'))+1)+' 頁':'';}).observe(document.querySelector('.deck'),{attributes:true,subtree:true,attributeFilter:['class']});if(innerWidth<600&&!location.search.includes('preview')){document.body.classList.add('reading');document.querySelector('#read').textContent='投影模式';}'''
